function readBundledJson(id){try{const node=document.getElementById(id),raw=node?.dataset.content||'';if(!raw)return[];const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch(error){console.error(`Invalid bundled data: ${id}`,error);return[];}}
window.LEGAL_CONTENT=readBundledJson('legalDataPayload');
