const pdfAddressCatalog=Array.isArray(addressBundle)?addressBundle:(addressBundle.records||[]);
const addressCategories=Array.isArray(addressBundle?.categories)?addressBundle.categories:[];
const inflationData=readBundledJson('inflationDataPayload');
const inheritanceData=readBundledJson('inheritanceDataPayload');

function readStore(key,fallback){try{if(!nativeApp?.secureGet)return fallback;const raw=nativeApp.secureGet(key);return raw?JSON.parse(raw):fallback;}catch{return fallback;}}
function writeStore(key,value){try{if(!nativeApp?.securePut)return false;return nativeApp.securePut(key,JSON.stringify(value));}catch{return false;}}

