const typeLabels={pleading:'نمونه لایحه',petition:'نمونه دادخواست',complaint:'نمونه شکواییه'};
function templateBody(type,title){const heading=typeLabels[type];return `${heading}: ${title}\n\nمرجع محترم رسیدگی‌کننده\nبا سلام و احترام\n\nمشخصات و سمت تنظیم‌کننده: [تکمیل شود]\nمشخصات طرف یا طرفین: [تکمیل شود]\nشماره پرونده/کلاسه: [در صورت وجود]\n\nموضوع و خواسته:\n[خواسته دقیق، منجز و متناسب با صلاحیت مرجع درج شود.]\n\nشرح مختصر وقایع:\n[وقایع به ترتیب زمانی، بدون مطالب زائد و همراه با تاریخ نوشته شود.]\n\nدلایل و مستندات:\n۱. [قرارداد/سند/رسید]\n۲. [اظهارنامه/مکاتبه/گواهی]\n۳. [شهادت/کارشناسی/تحقیق محلی حسب مورد]\n\nتحلیل و مستند قانونی:\n[مواد قانونی فقط پس از کنترل متن رسمی روز و انطباق با واقعیت پرونده درج شود.]\n\nدرخواست نهایی:\n[تصمیم مورد تقاضا، خسارات، هزینه دادرسی و سایر آثار به‌صورت روشن بیان شود.]\n\nنام، امضا و تاریخ\n\nهشدار: این قالب آموزشی است و بدون بررسی صلاحیت، مواعد، ادله و دفاع احتمالی طرف مقابل نباید ثبت یا تقدیم شود.`;}
const templates=Object.entries(templateGroups).flatMap(([type,titles])=>titles.map((title,i)=>({id:`${type}-${i+1}`,type,typeLabel:typeLabels[type],title:`${typeLabels[type]} ${title}`,meta:'قالب آموزشی قابل شخصی‌سازی',summary:`چارچوب اولیه برای ${title}`,materials:title,source:'https://www.eadil.com',status:'نیازمند تطبیق پرونده',content:templateBody(type,title)})));
