function makeSupplemental(kind,title,index){return{id:`${kind}-supp-${index+1}`,kind,title,reviewStatus:'راهنمای عمومی',definition:`راهنمای اولیه برای تشخیص عنوان «${title}» و آماده‌سازی پرونده؛ عنوان نهایی باید با واقعیت، ادله و متن رسمی روز تطبیق داده شود.`,elements:['احراز سمت و ذی‌نفعی','تعیین رفتار یا تعهد موضوع پرونده','انتساب و رابطه سببیت حسب مورد','کنترل صلاحیت، مهلت و دفاع احتمالی'],laws:'قانون ماهوی و مقررات آیین دادرسی مرتبط؛ شماره مواد پیش از اقدام از متن رسمی روز کنترل شود.',check:['شرح زمانی دقیق وقایع','مدارک و اصل اسناد','مشخصات کامل طرفین','کنترل صلاحیت مرجع','کنترل مواعد و ابلاغ‌ها','محاسبه خواسته یا ضرر','فهرست شهود و ادله الکترونیکی','درخواست نهایی روشن']};}
