function persist(){const keys=['calculations','officeSecurity','userProfile','legalOrders','typingOrders','collaborators','addresses','aiSettings'];if(officeDataLoaded)keys.push('clients','matters','hearings','notes');keys.forEach(k=>writeStore(k,state[k]));}
