function loadOfficeData(){if(officeDataLoaded)return;state.clients=readStore('clients',[]);state.matters=readStore('matters',[]);state.hearings=readStore('hearings',[]);state.notes=readStore('notes',{});officeDataLoaded=true;renderOffice();}
function clearOfficePlaintext(){if(!officeDataLoaded)return;state.clients=[];state.matters=[];state.hearings=[];state.notes={};officeDataLoaded=false;renderOffice();}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2800);}
function showPage(name){if(name==='office')lockOrShowOffice();$$('.page').forEach(p=>p.classList.toggle('active',p.dataset.page===name));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));const titles={home:'دستیار وکیل',library:'کتابخانه حقوقی',unity:'آرای وحدت رویه',opinions:'نظریات مشورتی',calculators:'محاسبات حقوقی',education:'چک‌لیست دعاوی',addresses:'نشانی‌ها و مراجع','address-category':activeAddressCategory||'نشانی‌ها',assistant:'هوش مصنوعی حقوقی',office:'دستیار وکیل',about:'درباره ما',profile:'حساب کاربری'};$('.topbar-title').textContent=titles[name]||'دستیار وکیل';if(name==='calculators'){const search=$('#calculatorSearch');if(search)search.value='';renderCalculators();const grid=$('#calculatorGrid');if(grid){grid.hidden=false;grid.classList.add('calculators-ready');void grid.offsetHeight;requestAnimationFrame(()=>grid.classList.add('calculators-visible'));}}window.scrollTo({top:0,behavior:'smooth'});$('#mainContent').focus({preventScroll:true});history.replaceState({page:name},'',`#${name}`);}
function openExternal(url){if(nativeApp?.openExternal)nativeApp.openExternal(url);else window.open(url,'_blank','noopener,noreferrer');}
function shareText(title,text){if(nativeApp?.shareText)return nativeApp.shareText(title,text);if(navigator.share)return navigator.share({title,text}).catch(()=>{});navigator.clipboard?.writeText(text);toast('متن برای اشتراک کپی شد.');}
function dial(phone){if(nativeApp?.openDialer)nativeApp.openDialer(phone);else location.href=`tel:${phone.replace(/[^0-9+]/g,'')}`;}
function mapSearch(query){if(nativeApp?.openMap)nativeApp.openMap(query);else openExternal(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`);}

function normalizeSearch(v){return latin(v).replace(/\s+/g,' ').trim().toLowerCase();}
function resourceHaystack(x){return normalizeSearch(`${x.title} ${x.meta} ${x.summary} ${x.materials||''} ${x.content}`);}
