function calculateDeadline(form){const base=form.baseDate.value,days=Number(form.days.value),direction=form.direction.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(base)||!Number.isInteger(days)||days<0||days>3650)throw Error('تاریخ و تعداد روز معتبر وارد کنید.');const date=new Date(`${base}T12:00:00`);if(!Number.isFinite(date.getTime()))throw Error('تاریخ مبنا معتبر نیست.');const include=form.includeStart.checked&&days>0?1:0;const signed=(direction==='subtract'?-1:1)*Math.max(0,days-include);date.setDate(date.getDate()+signed);return{iso:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,persian:new Intl.DateTimeFormat('fa-IR-u-ca-persian',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(date),gregorian:new Intl.DateTimeFormat('fa-IR-u-ca-gregory',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(date),days,direction};}
function calculate(item,form){const amount=Number(form.amount.value),rate=Number(form.rate.value);if(!Number.isFinite(amount)||!Number.isFinite(rate)||amount<0||rate<0)throw Error('ورودی معتبر نیست.');let result=0,lines=[];if(['percent','rate'].includes(item.mode)){result=amount*rate/100;lines=[['مبلغ مبنا',money(amount)],['نرخ',`${fa(rate)}٪`]];}else if(item.mode==='index'){result=amount*rate;lines=[['مبلغ اولیه',money(amount)],['ضریب',fa(rate)]];}else if(item.mode==='estate'){const d=amount*rate/100;result=Math.max(0,amount-d);lines=[['کل ترکه',money(amount)],['کسورات',money(d)]];}else if(item.mode==='unit'){result=amount*rate;lines=[['تعداد',fa(amount)],['تعرفه واحد',money(rate)]];}else{const months=Number(form.months.value);if(!Number.isInteger(months)||months<1||months>360)throw Error('مدت بازپرداخت باید بین ۱ تا ۳۶۰ ماه باشد.');const monthly=rate/1200;result=monthly===0?amount/months:amount*monthly*Math.pow(1+monthly,months)/(Math.pow(1+monthly,months)-1);lines=[['اصل',money(amount)],['نرخ',`${fa(rate)}٪`],['ماه',fa(months)],['جمع بازپرداخت',money(result*months)]];}if(!Number.isFinite(result)||result<0)throw Error('نتیجه قابل محاسبه نیست.');return{result,lines};}

function calculateInflation(form){const amount=Number(form.amount.value),dy=form.dueYear.value,dm=form.dueMonth.value,py=form.payYear.value,pm=form.payMonth.value;if(!Number.isFinite(amount)||amount<=0)throw Error('اصل دین را به ریال وارد کنید.');const due=inflationData.years?.[dy]?.months?.[dm],pay=inflationData.years?.[py]?.months?.[pm];if(!Number.isFinite(due)||!Number.isFinite(pay))throw Error('برای ماه انتخاب‌شده در جدول ارسالی شاخصی وجود ندارد.');if(Number(py)<Number(dy)||(py===dy&&(inflationData.months.indexOf(pm)<inflationData.months.indexOf(dm))))throw Error('زمان پرداخت نمی‌تواند پیش از سررسید باشد.');const result=amount*pay/due;return{result,lines:[['اصل دین',money(amount)],['شاخص سررسید',fa(due)],['شاخص پرداخت',fa(pay)],['ضریب شاخص',fa(pay/due)],['افزایش محاسباتی',money(result-amount)]]};}

function calculateInheritance(form){
 const estate=Number(form.amount.value),sons=Number(form.sons.value),daughters=Number(form.daughters.value),spouse=form.spouse.value,wives=Number(form.wives.value),father=form.father.checked,mother=form.mother.checked;
 if(!Number.isFinite(estate)||estate<=0||![sons,daughters,wives].every(Number.isInteger)||sons<0||daughters<0||wives<1||wives>4)throw Error('تعداد وراث و مبلغ ترکه را صحیح وارد کنید.');
 const descendants=sons+daughters>0,rows=[];let allocated=0;
 if(spouse==='husband'){const share=estate*(descendants?1/4:1/2);allocated+=share;rows.push(['سهم زوج',money(share)]);}
 if(spouse==='wife'){const total=estate*(descendants?1/8:1/4);allocated+=total;rows.push([wives>1?`سهم مجموع ${fa(wives)} زوجه`:'سهم زوجه',money(total)]);if(wives>1)rows.push(['سهم هر زوجه',money(total/wives)]);}
 if(descendants){if(mother){const share=estate/6;allocated+=share;rows.push(['سهم فرض مادر',money(share)]);}if(father){const share=estate/6;allocated+=share;rows.push(['سهم فرض پدر',money(share)]);}const residue=Math.max(0,estate-allocated);if(sons>0){const units=sons*2+daughters;const unit=residue/units;if(sons)rows.push(['سهم هر پسر',money(unit*2)]);if(daughters)rows.push(['سهم هر دختر',money(unit)]);allocated=estate;}else{const fixed=estate*(daughters===1?1/2:2/3);rows.push([daughters===1?'فرض یک دختر':'فرض دختران',money(fixed)]);rows.push(['باقیمانده/کسری نیازمند اعمال قواعد رد و ترکیب وراث',money(estate-allocated-fixed)]);allocated+=fixed;}}
 else if(father&&mother){const motherShare=estate/3;rows.push(['سهم مادر پیش از کنترل حاجب',money(motherShare)]);allocated+=motherShare;const fatherShare=Math.max(0,estate-allocated);rows.push(['سهم پدر از باقیمانده',money(fatherShare)]);allocated=estate;}
 else if(father||mother){const label=father?'سهم پدر':'سهم مادر';rows.push([`${label} از باقیمانده`,money(Math.max(0,estate-allocated))]);allocated=estate;}
 else if(spouse==='none')throw Error('حداقل یکی از وراث طبقه اول را مشخص کنید.');
 if(!descendants&&!father&&!mother&&spouse!=='none')rows.push(['باقیمانده متعلق به سایر وراث/طبقات',money(estate-allocated)]);
 return{result:Math.max(0,allocated),lines:[['خالص ترکه',money(estate)],...rows],partial:allocated<estate};
}

