 if($('#savedAddressList'))$('#savedAddressList').innerHTML=state.addresses.length?state.addresses.map(x=>`<article class="list-item"><div class="list-item-head"><div><strong>${esc(x.name)}</strong><p>${esc(x.city)} · ${esc(x.query)}</p></div><button class="danger-button" data-delete-kind="addresses" data-delete-id="${x.id}">حذف</button></div><div class="card-actions"><button class="text-button" data-map-query="${esc(x.query)}">مسیریاب</button>${x.phone?`<button class="text-button" data-dial="${esc(x.phone)}">تماس</button>`:''}</div></article>`).join(''):'<div class="empty-state">نشانی شخصی ذخیره نشده است.</div>';
