function orderText(kind,id){const x=kind==='legal'?state.legalOrders.find(i=>i.id===id):state.typingOrders.find(i=>i.id===id);if(!x)return'';return kind==='legal'?`سفارش ${x.type}\nنام: ${x.name}\nتماس: ${x.phone}\nموضوع: ${x.subject}\nشرح و مهلت: ${x.description}\nهزینه: پس از بررسی و تأیید طرفین`:`سفارش تایپ و صفحه‌آرایی\nنام: ${x.name}\nتماس: ${x.phone}\nخدمت: ${x.service}\nتعداد تقریبی: ${x.pages} صفحه\nتوضیحات: ${x.description}\nهزینه: پس از بررسی و تأیید طرفین`;}
