document.addEventListener('submit',e=>{const f=e.target.closest('#activeCalculatorForm');if(!f)return;e.preventDefault();const item=calculators.find(x=>x.id===f.dataset.id);try{if(item.mode==='date'){const c=calculateDeadline(f.elements);$('#calculatorResult').innerHTML=`<section class="result-panel date-result"><small>تاریخ نتیجه</small><strong>${esc(c.persian)}</strong><p>${esc(c.gregorian)}</p><code dir="ltr">${c.iso}</code><button id="saveCalculation" class="text-button">ذخیره نتیجه</button></section>`;$('#saveCalculation').onclick=()=>{state.calculations.unshift({id:nowId(),calculator:item.title,result:c.iso,date:new Date().toLocaleDateString('fa-IR')});persist();toast('تاریخ محاسبه‌شده ذخیره شد.');};return;}const c=item.mode==='inflation'?calculateInflation(f.elements):item.mode==='inheritance'?calculateInheritance(f.elements):calculate(item,f.elements);$('#calculatorResult').innerHTML=`<section class="result-panel"><strong>${c.partial?'نتیجه جزئی قابل محاسبه':money(c.result)}</strong><ul class="breakdown">${c.lines.map(x=>`<li><span>${esc(x[0])}</span><b>${esc(x[1])}</b></li>`).join('')}</ul><button id="saveCalculation" class="text-button">ذخیره</button></section>`;$('#saveCalculation').onclick=()=>{state.calculations.unshift({id:nowId(),calculator:item.title,result:c.result,date:new Date().toLocaleDateString('fa-IR')});persist();toast('محاسبه ذخیره شد.');};}catch(err){toast(err.message);}});

$('#clientForm').addEventListener('submit',e=>{e.preventDefault();const nationalId=value('#clientNationalId');if(!validateNationalId(nationalId))return toast('کد ملی از نظر ساختار صحیح نیست.');state.clients.unshift({id:nowId(),name:value('#clientName'),birthDate:value('#clientBirthDate'),nationalId,phone:value('#clientPhone'),powerNumber:value('#clientPowerNumber')});persist();e.target.reset();renderOffice();setOfficeMode('clients','list');toast('موکل ثبت شد.');});
$('#matterForm').addEventListener('submit',e=>{e.preventDefault();state.matters.unshift({id:nowId(),clientName:value('#matterClientName'),subject:value('#matterSubject'),number:value('#matterNumber'),archiveNumber:value('#matterArchiveNumber'),branch:value('#matterBranch'),notes:value('#matterNotes')});persist();e.target.reset();renderOffice();setOfficeMode('matters','list');toast('پرونده ثبت شد.');});
$('#hearingReminder').addEventListener('change',e=>{$('#hearingReminderAt').disabled=!e.target.checked;});
$('#hearingForm').addEventListener('submit',e=>{e.preventDefault();const dateTime=value('#hearingDateTime'),hearingAt=new Date(dateTime).getTime(),reminder=$('#hearingReminder').checked,reminderAt=value('#hearingReminderAt'),trigger=new Date(reminderAt).getTime();if(!Number.isFinite(hearingAt)||hearingAt<=Date.now())return toast('زمان رسیدگی باید در آینده باشد.');if(reminder&&(!Number.isFinite(trigger)||trigger<=Date.now()||trigger>=hearingAt))return toast('زمان هشدار باید در آینده و پیش از زمان رسیدگی باشد.');const item={id:nowId(),dateTime,branch:value('#hearingBranch'),reminder,reminderAt:reminder?reminderAt:''};let reminderMessage='وقت رسیدگی ثبت شد.';if(reminder){const ok=nativeApp?.scheduleReminder?nativeApp.scheduleReminder(item.id,trigger,'یادآوری وقت رسیدگی',`${item.branch} — ${formatDateTime(dateTime)}`):false;item.reminder=!!ok;if(!ok)reminderMessage=nativeApp?'وقت ثبت شد؛ مجوز اعلان را تأیید و سپس هشدار را دوباره فعال کنید.':'وقت ثبت شد؛ هشدار بومی فقط در APK فعال است.';}state.hearings.unshift(item);persist();e.target.reset();$('#hearingReminder').checked=true;$('#hearingReminderAt').disabled=false;renderOffice();setOfficeMode('hearings','list');toast(reminderMessage);});

$('#officePinUnlockForm').addEventListener('submit',async e=>{e.preventDefault();const now=Date.now();if(now<pinBlockedUntil)return toast(`پس از ${Math.ceil((pinBlockedUntil-now)/1000)} ثانیه دوباره تلاش کنید.`);const pin=latin(value('#officeUnlockPin'));if(!/^\d{4}$/.test(pin))return toast('رمز باید چهار رقم باشد.');let ok=false;try{ok=await verifyPin(pin);}catch(error){return toast(error.message);}if(!ok){pinAttempts++;if(pinAttempts>=5){const rounds=Math.min(6,Math.floor(pinAttempts/5));pinBlockedUntil=Date.now()+60000*Math.pow(2,rounds-1);}persistThrottle();return toast(pinBlockedUntil>Date.now()?'به‌دلیل تلاش‌های ناموفق، ورود موقتاً قفل شد.':`رمز نادرست است؛ ${fa(Math.max(0,5-(pinAttempts%5)))} تلاش تا وقفه باقی مانده.`);}pinAttempts=0;pinBlockedUntil=0;persistThrottle();officeLocked=false;loadOfficeData();e.target.reset();lockOrShowOffice();toast('دفتر باز شد.');});
$('#officeDeviceUnlock').addEventListener('click',()=>{if(nativeApp?.authenticateDevice)nativeApp.authenticateDevice();else toast('اثر انگشت یا پترن فقط در APK فعال است.');});
$('#lockOfficeNow').addEventListener('click',lockOffice);

$('#profileForm').addEventListener('submit',e=>{e.preventDefault();state.userProfile={name:value('#profileName'),phone:value('#profilePhone'),city:value('#profileCity'),license:value('#profileLicense')};persist();toast('پنل کاربری ذخیره شد.');renderAddresses();});
$('#officePinToggle').addEventListener('change',e=>{const wanted=e.target.checked,current=!!state.officeSecurity.pinEnabled;e.target.checked=current;if(wanted===current)return;if(wanted){$('#pinSetupFields').hidden=false;return;}requireFreshAuth('غیرفعال‌کردن رمز دفتر',()=>{state.officeSecurity.pinEnabled=false;state.officeSecurity.pinSalt='';state.officeSecurity.pinHash='';state.officeSecurity.pinVersion=2;persist();if(officeProtected()){officeLocked=true;clearOfficePlaintext();}else{officeLocked=false;loadOfficeData();}renderProfile();lockOrShowOffice();toast('رمز چهاررقمی غیرفعال شد.');});});
$('#saveOfficePin').addEventListener('click',()=>{const a=latin(value('#officePinNew')),b=latin(value('#officePinConfirm'));if(!/^\d{4}$/.test(a))return toast('رمز باید دقیقاً چهار رقم باشد.');if(a!==b)return toast('تکرار رمز یکسان نیست.');const applyPin=async()=>{const salt=randomSalt(),iterations=210000;state.officeSecurity.pinSalt=salt;state.officeSecurity.pinHash=await pinHash(a,salt,iterations);state.officeSecurity.pinVersion=2;state.officeSecurity.pinIterations=iterations;state.officeSecurity.pinEnabled=true;persist();$('#officePinNew').value=$('#officePinConfirm').value='';officeLocked=true;clearOfficePlaintext();renderProfile();lockOrShowOffice();toast('رمز دستیار وکیل با موفقیت ثبت شد.');};requireFreshAuth(state.officeSecurity.pinEnabled?'تغییر رمز دفتر':'افزودن رمز دفتر',()=>applyPin().catch(error=>toast(error.message)));});
$('#officeDeviceToggle').addEventListener('change',e=>{const wanted=e.target.checked,current=!!state.officeSecurity.deviceEnabled;e.target.checked=current;if(wanted===current)return;if(wanted&&!nativeApp)return toast('این گزینه فقط داخل APK فعال است.');requireFreshAuth(wanted?'فعال‌کردن قفل دستگاه':'غیرفعال‌کردن قفل دستگاه',()=>{state.officeSecurity.deviceEnabled=wanted;persist();officeLocked=officeProtected();if(officeLocked)clearOfficePlaintext();else loadOfficeData();renderProfile();lockOrShowOffice();toast(wanted?'قفل دستگاه برای دفتر فعال شد.':'قفل دستگاه غیرفعال شد.');});});
