$('#exportWord').addEventListener('click',()=>{const scope=value('#exportScope');if(!exportSections(scope).length)return toast('داده‌ای برای خروجی وجود ندارد.');if(nativeApp?.exportWord){nativeApp.exportWord('گزارش-دستیار-وکیل.docx',wordXml(scope));toast('محل ذخیره Word را انتخاب کنید.');}else toast('خروجی Word بومی در APK فعال است.');});
$('#exportPdf').addEventListener('click',()=>{const scope=value('#exportScope');if(!exportSections(scope).length)return toast('داده‌ای برای خروجی وجود ندارد.');if(nativeApp?.printHtml)nativeApp.printHtml('گزارش دستیار وکیل',exportHtml(scope));else{const w=window.open('','_blank');w.document.write(exportHtml(scope));w.document.close();w.print();}});
$('#assistantForm').addEventListener('submit',e=>{e.preventDefault();const text=value('#assistantInput').trim();if(!text)return;if(!$('#aiConsent').checked)return toast('برای ارسال آنلاین، رضایت پردازش توسط سرویس ثالث را تأیید کنید.');if(!nativeApp?.askLegalAi){appendMessage('user',text);appendMessage('bot',offlineReply(text));return toast('پیش‌نمایش مرورگر از راهنمای آفلاین استفاده کرد؛ سرویس آنلاین داخل APK فعال است.');}const configured=configuredAiProviders(),mode=value('#aiMode'),providers=mode==='council'?configured:configured.filter(x=>x===mode);if(!providers.length)return toast('ابتدا کلید ارائه‌دهنده انتخابی را در تنظیمات همین صفحه ذخیره کنید.');appendMessage('user',text);$('#assistantInput').value='';const batch={id:nowId(),question:text,remaining:providers.length,results:{}};for(const provider of providers){const requestId=`${batch.id}:${provider}`;pendingAi.set(requestId,mode==='council'?{kind:'council',provider,batch}:{kind:'single',provider});requestAi(provider,legalAiPrompt(text),requestId);}toast(`${fa(providers.length)} سرویس در حال تحلیل است.`);});
$$('[data-prompt]').forEach(b=>b.addEventListener('click',()=>{$('#assistantInput').value=b.dataset.prompt;$('#assistantForm').requestSubmit();}));
$('#themeButton').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'light':'dark';localStorage.setItem('lawyer_theme',dark?'light':'dark');});
function eraseLocalAccount(){state.hearings.forEach(x=>nativeApp?.cancelReminder?.(String(x.id)));['clients','matters','hearings','calculations','legalOrders','typingOrders','collaborators','addresses'].forEach(k=>state[k]=[]);state.notes={};state.officeSecurity={pinEnabled:false,pinSalt:'',pinHash:'',pinVersion:2,pinIterations:210000,deviceEnabled:false,autoLock:true};state.userProfile={name:'',phone:'',city:'',license:''};officeDataLoaded=true;persist();nativeApp?.deleteProfessionalData?.();pinAttempts=0;pinBlockedUntil=0;officeLocked=false;renderAll();showPage('home');toast('حساب محلی و همه اطلاعات این دستگاه حذف شد.');}
$('#deleteAccount').addEventListener('click',()=>{$('#deleteAccountPhrase').value='';$('#confirmDeleteAccount').disabled=true;$('#deleteAccountDialog').showModal();});
$('#deleteAccountPhrase').addEventListener('input',e=>{$('#confirmDeleteAccount').disabled=e.target.value.trim()!=='حذف حساب';});
$('#deleteAccountDialog').addEventListener('close',e=>{if(e.target.returnValue==='confirm'&&value('#deleteAccountPhrase')==='حذف حساب')requireFreshAuth('تأیید نهایی حذف همه اطلاعات',eraseLocalAccount);});
$('#sensitiveAuthPinForm').addEventListener('submit',e=>{e.preventDefault();authorizeSensitivePin();});
$('#sensitiveAuthDevice').addEventListener('click',()=>{if(nativeApp?.authenticateDevice)nativeApp.authenticateDevice();else toast('قفل امن دستگاه فقط در APK فعال است.');});
$('#cancelSensitiveAuth').addEventListener('click',cancelSensitiveAction);
$('#sensitiveAuthDialog').addEventListener('cancel',e=>{e.preventDefault();cancelSensitiveAction();});
$('#emailCreator').addEventListener('click',()=>{if(nativeApp?.composeEmail)nativeApp.composeEmail('majid.gharaee1369@gmail.com','ارتباط با دفتر وکالت دکتر مجید قرایی','با سلام،\n');else toast('برنامه ایمیل روی دستگاه در دسترس نیست.');});
$('#openAlarmSettings').addEventListener('click',()=>{if(nativeApp?.openAlarmSettings)nativeApp.openAlarmSettings();else toast('تنظیمات هشدار در APK قابل دسترسی است.');});

window.handleNativeBack=()=>{const active=$('.page.active')?.dataset.page;if(active&&active!=='home'){showPage('home');return 'home';}return 'exit';};
function renderAll(){renderLibrary();renderCalculators();renderEducation();renderOffice();renderProfile();renderOrders();renderCollaborators();renderAddresses();renderReminderCapability();refreshAiProviderState();lockOrShowOffice();}
document.documentElement.dataset.theme=localStorage.getItem('lawyer_theme')||'light';
refreshLocalLegalCatalog();
renderAll();
startLegalCatalogSync();
const initialPage=location.hash.replace(/^#/,'');if(initialPage&&$(`[data-page="${initialPage}"]`)){showPage(initialPage);if(initialPage==='unity')renderUnityYears();if(initialPage==='opinions')renderOpinionYears();}
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
